import{_ as s,o as i,c as n,a2 as e}from"./chunks/framework.B-kZW7D6.js";const k=JSON.parse('{"title":"Man 命令查出来的数字是啥意思","description":"Unix Man 相关命令","frontmatter":{"title":"Man 命令查出来的数字是啥意思","description":"Unix Man 相关命令","tags":["转载","unix","shell"]},"headers":[],"relativePath":"zh/blogs/20190901/index.md","filePath":"zh/blogs/20190901/index.md"}'),l={name:"zh/blogs/20190901/index.md"};function t(p,a,h,o,r,d){return i(),n("div",null,[...a[0]||(a[0]=[e(`<nav class="table-of-contents"><ul><li><a href="#man-命令">man 命令</a><ul><li><a href="#查询某个命令的帮助页面">查询某个命令的帮助页面</a></li><li><a href="#在-man-page-中检索关键字的例子">在 man page 中检索关键字的例子</a></li><li><a href="#打开所有匹配到的-man-pages">打开所有匹配到的 man pages</a></li></ul></li><li><a href="#info">Info</a></li><li><a href="#usr-share-doc">/usr/share/doc</a></li></ul></nav><p>转自 <a href="https://www.cyberciti.biz/faq/howto-use-linux-unix-man-pages/" target="_blank" rel="noreferrer">Linux / UNIX: Getting help with man pages and how to use them</a></p><p>在读一些文档的时候看到如 <a href="https://cmake.org/cmake/help/latest/manual/cmake-commands.7.html" target="_blank" rel="noreferrer">cmake-commands(7)</a>，<a href="https://man7.org/linux/man-pages/man2/bpf.2.html" target="_blank" rel="noreferrer">bpf(2)</a>，不知道数字是啥意思……查阅后原来是 man 的章节分类，记录一下：</p><ul><li>Section # 1 : User command (executable programs or shell commands)</li><li>Section # 2 : System calls (functions provided by the kernel)</li><li>Section # 3 : Library calls (functions within program libraries)</li><li>Section # 4 : Special files (usually found in /dev)</li><li>Section # 5 : File formats and conventions eg /etc/passwd</li><li>Section # 6 : Games</li><li>Section # 7 : Miscellaneous (including macro packages and conventions),</li><li>Section # 8 : System administration commands (usually only for root)</li><li>Section # 9 : Kernel routines [Non standard]</li></ul><p>所以，<code>useradd(8)</code> 指代的就来自 sys admin section # 8 的 user add 命令的文档。</p><h1 id="原文节选-怎样科学阅读-linux-下的-man-pages" tabindex="-1">原文节选：怎样科学阅读 Linux 下的 man pages <a class="header-anchor" href="#原文节选-怎样科学阅读-linux-下的-man-pages" aria-label="Permalink to &quot;原文节选：怎样科学阅读 Linux 下的 man pages&quot;">​</a></h1><h2 id="man-命令" tabindex="-1">man 命令 <a class="header-anchor" href="#man-命令" aria-label="Permalink to &quot;man 命令&quot;">​</a></h2><p>man 命令可以用来打印 man (manual) pages。</p><p>man 命令格式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {command-name}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {section}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {command-name}</span></span></code></pre></div><p>例如，查看 clear 命令的帮助页面：<code>man clear</code>。</p><p>查看特定章节：<code>man 5 passwd</code>。</p><h3 id="查询某个命令的帮助页面" tabindex="-1">查询某个命令的帮助页面 <a class="header-anchor" href="#查询某个命令的帮助页面" aria-label="Permalink to &quot;查询某个命令的帮助页面&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> printf</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf (1)           - format and print data</span></span>
<span class="line"><span>printf (3)           - formatted output conversion</span></span></code></pre></div><p>这等价于</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whatis</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> printf</span></span></code></pre></div><h3 id="在-man-page-中检索关键字的例子" tabindex="-1">在 man page 中检索关键字的例子 <a class="header-anchor" href="#在-man-page-中检索关键字的例子" aria-label="Permalink to &quot;在 man page 中检索关键字的例子&quot;">​</a></h3><p>找到所有带有该关键字的命令的帮助内容。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> printf</span></span></code></pre></div><p>等价于</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apropos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> printf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apropos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span></span></code></pre></div><h3 id="打开所有匹配到的-man-pages" tabindex="-1">打开所有匹配到的 man pages <a class="header-anchor" href="#打开所有匹配到的-man-pages" aria-label="Permalink to &quot;打开所有匹配到的 man pages&quot;">​</a></h3><p>类似 <code>man -k</code> ，但是这次会直接打开它们的详情页，可以按 <code>[Enter]/[CTRL+D]</code>键跳过。</p><h2 id="info" tabindex="-1">Info <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Info&quot;">​</a></h2><p>也可以通过 <code>info</code> 命令查看文档，有时比 man 提供的内容更加丰富，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> date</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> date</span></span></code></pre></div><p>Info 页面的命令</p><ul><li>q – 退出 info 页面</li><li>n – 下一章</li><li>p – 上一章</li><li>u – 上一层</li></ul><h2 id="usr-share-doc" tabindex="-1">/usr/share/doc <a class="header-anchor" href="#usr-share-doc" aria-label="Permalink to &quot;/usr/share/doc&quot;">​</a></h2><p><code>/usr/share/doc</code> 下也有一些有趣的帮助文档。</p><p>除了本文外，该系列还有几则安装和使用 Man 的教程：</p><ul><li>How to add/install man pages in Alpine Linux</li><li>How to install man pages on a CentOS Linux 6/7</li><li>Unix / Linux: Display Color Man Pages</li><li>HowTo: Linux / UNIX Create a Manpage</li><li>Ubuntu Linux install man pages</li></ul>`,34)])])}const g=s(l,[["render",t]]);export{k as __pageData,g as default};
